(async () => {
  const { env } = process;
  const action = env.ACTION;
  if (!action) throw new Error('Missing required ACTION env var');
  const portRaw = env.PORT;
  const openRaw = env.OPEN;
  const args = [action];
  if (portRaw !== undefined) {
    const port = Number(portRaw);
    if (Number.isNaN(port)) throw new Error('PORT must be a number');
    args.push('--port', String(port));
  }
  if (openRaw !== undefined) {
    const open = openRaw === 'true';
    if (open) args.push('--open');
  }
  globalThis.hermesArgs = args;
})();

(async () => {
  const { spawn } = await import('node:child_process');
  const path = await import('node:path');
  const args = globalThis.hermesArgs;
  const binPath = path.resolve('node_modules', '@bitseek', 'hermes-webui', 'bin', 'hermes-webui.mjs');
  const child = spawn(process.execPath, [binPath, ...args], { stdio: ['ignore', 'pipe', 'pipe'] });
  let stdout = '';
  let stderr = '';
  for await (const chunk of child.stdout) { stdout += chunk; }
  for await (const chunk of child.stderr) { stderr += chunk; }
  const exitCode = await new Promise(resolve => child.on('close', resolve));
  globalThis.hermesResult = { stdout, stderr, exitCode };
})();

(async () => {
  const result = globalThis.hermesResult;
  console.log(JSON.stringify({
    output: result.stdout.trim(),
    exit_code: result.exitCode,
    error: result.stderr.trim()
  }));
})();
